$new=$fixture;$new['checked_at']='2026-09-02T00:00:00+00:00';$new['seo']['data']['meta']['title']='Updated title';$two=$store->record($new);hc($two['snapshot_id']!==$one['snapshot_id'],'updated data creates immutable snapshot');hc($store->report($fixture['domain'],$one['snapshot_id'])['result']['seo']['data']['meta']['title']==='History fixture 标题','old link retains original content');hc($store->report($fixture['domain'])['id']===$two['snapshot_id'],'fixed URL follows latest data');hc(count($store->versions($fixture['domain']))===2,'version history');$store->record($fixture,false);hc($store->report($fixture['domain'])['id']===$two['snapshot_id'],'older cache import cannot roll back latest report');
$traffic=$new;$traffic['traffic']=['status'=>'ok','provider'=>'TabAPI','checked_at'=>'2026-09-03T00:00:00+00:00','data'=>['domain'=>$fixture['domain'],'month'=>'2026-08','monthly_visits'=>0]];$three=$store->record($traffic);hc($store->report($fixture['domain'])['result']['traffic']['data']['monthly_visits']===0,'real zero retained');hc($store->report($fixture['domain'])['data_updated_at']==='2026-09-03T00:00:00+00:00','latest component timestamp retained');
hc($store->search('NEEDLE-KEYWORD')['total']===1,'case-insensitive keyword search');hc($store->search('独立报告')['total']===1,'description search');hc($store->search('missing')['total']===0,'empty search match');
foreach(range(1,23) as $i){$r=hf('paged-'.$i.'.example.org');$r['seo']['data']['meta']['keywords']='paging';$store->record($r,false);}
$paged=$store->search('paged-',2,20);hc($paged['total']===23&&$paged['pages']===2&&count($paged['items'])===3,'search pagination');hc($store->search('paged-',1,20)['items'][0]['domain']!==$paged['items'][0]['domain'],'stable distinct pages');hc($store->search('',1,20)['total']===24,'one list item per domain');$fresh=new HistoryStore($dir);hc($fresh->search()['total']===24,'storage survives object/process lifetime');hc($fresh->sitemapPage(1,10)['pages']===3,'sitemap sharding');
hp(fn()=>$store->search('',0),'invalid_page');hp(fn()=>$store->search(str_repeat('中',101)),'invalid_search');hp(fn()=>$store->report('history-fixture.example.com','../../outside'),'invalid_snapshot');hp(fn()=>$store->record(['domain'=>'127.0.0.1']),'invalid_domain');hp(fn()=>$store->record(['domain'=>'valid.example.com']),'history_invalid_result');hc($store->report('other.example.com',$one['snapshot_id'])===null,'no cross-domain snapshot lookup');
