file_put_contents($dir.'/index.json','invalid');hp(fn()=>$store->search(),'history_corrupt');hp(fn()=>$store->record($fixture),'history_corrupt');hc(file_get_contents($dir.'/index.json')==='invalid','corrupt index not silently replaced');hc($store->report($fixture['domain'],$one['snapshot_id'])!==null,'fixed snapshot readable even with corrupt listing index');
